<script setup lang="ts">
import {ref,computed,onMounted} from 'vue';import {companyOptions,api,clp,date,errorText,currentPeriod} from '../api';import {useAuth} from '../stores/auth';import PageHeading from '../components/PageHeading.vue';import StatusBadge from '../components/StatusBadge.vue';import Modal from '../components/Modal.vue';import {Plus} from 'lucide-vue-next';
const auth=useAuth(),charges=ref<any[]>([]),companies=ref<any[]>([]),period=ref(currentPeriod()),error=ref(''),busy=ref(false),loading=ref(true),selected=ref<any>(null),show=ref(false);const today=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Santiago',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());const payment=ref({amount:0,paid_on:today,reference:''});const form=ref({company_id:'',description:'Honorario extraordinario',period:period.value,amount:150000,due_on:today});const total=computed(()=>charges.value.reduce((n,c)=>n+c.amount,0)),paid=computed(()=>charges.value.reduce((n,c)=>n+c.paid,0));async function load(){loading.value=true;try{charges.value=(await api.get('/charges',{params:{period:period.value}})).data;}catch(e){error.value=errorText(e);}finally{loading.value=false;}}function open(c:any){selected.value=c;payment.value={amount:c.balance,paid_on:today,reference:crypto.randomUUID()};error.value='';}async function savePayment(){busy.value=true;try{await api.post(`/charges/${selected.value.id}/payments`,payment.value);selected.value=null;await load();}catch(e){error.value=errorText(e);}finally{busy.value=false;}}async function create(){busy.value=true;try{await api.post('/charges',form.value);show.value=false;await load();}catch(e){error.value=errorText(e);}finally{busy.value=false;}}onMounted(async()=>{await load();if(auth.admin)try{companies.value=await companyOptions();}catch(e){error.value=errorText(e);}});
</script>
<template><PageHeading title="Honorarios" subtitle="Servicios del estudio, pagos registrados y saldos claros."><label class="inline-label">Período<input type="month" v-model="period" @change="load"></label><button v-if="auth.admin" class="button primary" @click="show=true"><Plus :size="16"/>Nuevo cargo</button></PageHeading><p v-if="error" class="error" role="alert">{{error}}</p><div class="stats-grid"><div class="stat"><span class="stat-label">Honorarios del período</span><strong>{{clp(total)}}</strong><small>{{charges.length}} cargos</small></div><div class="stat"><span class="stat-label">Pagos registrados</span><strong>{{clp(paid)}}</strong><small>Incluye pagos parciales</small></div><div class="stat"><span class="stat-label">Saldo pendiente</span><strong>{{clp(total-paid)}}</strong><small>Por cobrar</small></div></div><p v-if="loading" class="empty">Cargando honorarios…</p><section v-else class="panel"><div class="table-wrap"><table><thead><tr><th>Empresa / Concepto</th><th>Monto</th><th>Saldo</th><th>Vencimiento</th><th>Estado</th><th></th></tr></thead><tbody><tr v-for="c in charges" :key="c.id"><td><strong>{{c.company.name}}</strong><small>{{c.description}} · {{c.period}}</small></td><td class="money">{{clp(c.amount)}}</td><td class="money">{{clp(c.balance)}}</td><td>{{date(c.due_on)}}</td><td><StatusBadge :status="c.payment_status"/></td><td><button class="button" @click="open(c)">{{auth.admin&&c.balance?'Registrar pago':'Ver pagos'}}</button></td></tr></tbody></table><p v-if="!charges.length" class="empty">No hay cargos para este período.</p></div><div class="panel-note">Estos cargos corresponden a honorarios. No representan impuestos ni facturas tributarias emitidas.</div></section><Modal v-if="selected" :title="selected.company.name" @close="selected=null"><p>Saldo pendiente: <strong>{{clp(selected.balance)}}</strong></p><div v-for="p in selected.payments" :key="p.id" class="list-row"><div><strong>{{clp(p.amount)}}</strong><small>{{date(p.paid_on)}} · {{p.reference}}</small></div><StatusBadge status="paid"/></div><p v-if="!selected.payments.length" class="empty compact">Sin pagos registrados.</p><form v-if="auth.admin&&selected.balance" @submit.prevent="savePayment" class="stack-form"><label>Monto CLP<input type="number" v-model.number="payment.amount" min="1" :max="selected.balance" required></label><label>Fecha del pago<input type="date" v-model="payment.paid_on" :max="today" required></label><label>Referencia / Identificador del pago<input v-model="payment.reference" maxlength="100" required></label><p v-if="error" class="error">{{error}}</p><button class="button primary" :disabled="busy">Registrar pago</button></form></Modal><Modal v-if="show" title="Nuevo cargo de honorarios" @close="show=false"><form @submit.prevent="create" class="stack-form"><label>Empresa<select v-model="form.company_id" required><option value="" disabled>Selecciona una empresa</option><option v-for="c in companies" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>Concepto<input v-model="form.description" required maxlength="180"></label><label>Período<input type="month" v-model="form.period" required></label><label>Monto CLP<input type="number" v-model.number="form.amount" min="1" required></label><label>Vencimiento pactado<input type="date" v-model="form.due_on" required></label><p v-if="error" class="error">{{error}}</p><button class="button primary" :disabled="busy">Crear cargo</button></form></Modal></template>
